public:
    bool isHappy(int n) {
        int slow = n, fast = n;
        do {
            slow = next(slow);
            fast = next(next(fast));
        } while (slow != fast);
        return slow == 1;
    }
    int next(int n) {
        int sum = 0;
        while (n) { sum += (n % 10) * (n % 10); n /= 10; }
        return sum;
    }
};

